#include <random>
#include <vector>
#include <iostream>
#include <set>
#include <map>
#include <algorithm>

using namespace std;

#define fi first
#define se second
#define all(x) (x).begin(), (x).end()
#define ll long long
#define pii pair<int, int>
#define pb emplace_back

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n);
        for (auto &c : a) cin >> c;
        int mx = 0;
        for (int i = 0; i < n - 1; i++) mx = max(mx, a[i]);
        cout << mx + a[n - 1] << "\n";
    }
    return 0;
}
